# ===========================================================================
# SAFE REVIT HELPERS
# ===========================================================================

def safe_element_name(element):
    if element is None:
        return ""
    try:
        value = element.Name
        if value:
            return str(value)
    except Exception:
        pass
    try:
        p = element.get_Parameter(BuiltInParameter.SYMBOL_NAME_PARAM)
        if p is not None:
            value = p.AsString()
            if value:
                return value
    except Exception:
        pass
    return ""


def safe_family_name(symbol):
    if symbol is None:
        return ""
    try:
        value = symbol.FamilyName
        if value:
            return str(value)
    except Exception:
        pass
    try:
        family = symbol.Family
        if family is not None:
            value = family.Name
            if value:
                return str(value)
    except Exception:
        pass
    return ""


def safe_symbol_name(symbol):
    if symbol is None:
        return ""
    try:
        value = symbol.Name
        if value:
            return str(value)
    except Exception:
        pass
    try:
        p = symbol.get_Parameter(BuiltInParameter.SYMBOL_NAME_PARAM)
        if p is not None:
            value = p.AsString()
            if value:
                return value
    except Exception:
        pass
    return ""


def safe_element_id_value(element_id):
    if element_id is None:
        return None
    try:
        return int(element_id.Value)
    except Exception:
        pass
    try:
        return int(element_id.IntegerValue)
    except Exception:
        pass
    try:
        return int(str(element_id))
    except Exception:
        return None


def get_instance_family_name(instance):
    if instance is None:
        return ""
    try:
        return safe_family_name(instance.Symbol)
    except Exception:
        return ""


def normalize_code(text):
    if text is None:
        return ""
    raw = str(text).replace("\\P", " ")
    raw = re.sub(r"\s+", " ", raw)
    return raw.upper().strip()


def name_key(value):
    return re.sub(r"[^A-Z0-9]", "", str(value or "").upper())


def name_tokens(value):
    return re.findall(r"[A-Z0-9]+", str(value or "").upper())


def score_symbol_candidate(code, family_hint, type_hint, family_name, type_name):
    code_k = name_key(code)
    hint_k = name_key(type_hint)
    fam_k = name_key(family_name)
    typ_k = name_key(type_name)
    hint_fam = name_key(family_hint)
    score = 0
    if hint_k and typ_k == hint_k:
        score += 120
    if code_k and typ_k == code_k:
        score += 110
    if hint_k and (hint_k in typ_k or typ_k in hint_k):
        score += 70
    if code_k and code_k in typ_k:
        score += 60
    if hint_fam and fam_k == hint_fam:
        score += 40
    elif hint_fam and (hint_fam in fam_k or fam_k in hint_fam):
        score += 20
    code_tokens = set(name_tokens(code))
    hint_tokens = set(name_tokens(type_hint))
    type_tokens = set(name_tokens(type_name))
    ignore = {"THE", "AND", "END", "PANEL", "GONDOLA", "FAMILY"}
    if code_tokens and type_tokens:
        overlap = (code_tokens & type_tokens) - ignore
        score += 8 * len(overlap)
        extra = type_tokens - code_tokens - hint_tokens - ignore
        score -= 6 * len(extra)
        if "T2" in code_tokens and "T2" in type_tokens and "ARM" in type_tokens:
            score += 50
            if "ONLY" in code_tokens and "TABLE" in type_tokens and "ARM" in type_tokens:
                score -= 35
        if "6WAY" in code_k and "6WAY" in typ_k:
            score += 80
        if "6" in code_tokens and "WAY" in type_tokens:
            score += 40
        if "16" in code_tokens and "WAY" in type_tokens:
            score += 40
    return score


def normalize_angle(angle):
    try:
        angle = float(angle)
    except Exception:
        return None
    angle = angle % 360.0
    if angle < 0:
        angle += 360.0
    return angle


def get_json_angle(g):
    """
    Prefer the traced gondola axis. Never consume DXF TEXT 'rotation'.
    """
    for key in (
        "placement_angle",
        "orientation_angle",
        "geometry_angle",
        "axis_angle",
        "angle",
        "angle_deg",
    ):
        value = g.get(key, None)
        if value is None or value == "":
            continue
        try:
            return normalize_angle(float(value) * ANGLE_SIGN + ANGLE_OFFSET_DEG)
        except Exception:
            pass
    return None


def get_orientation(g, cad_rotation_deg, family_name):
    orientation = str(g.get("orientation", "") or "").upper().strip()
    json_angle = get_json_angle(g) if USE_JSON_ANGLE else None
    source = "fallback"

    if json_angle is not None:
        angle = json_angle
        source = "JSON placement/orientation angle"
        if not orientation:
            orientation = "ANGLE"
    elif orientation == "HORIZONTAL":
        angle = normalize_angle(HORIZONTAL_FALLBACK_DEG)
        source = "fallback horizontal"
    elif orientation == "VERTICAL":
        angle = normalize_angle(VERTICAL_FALLBACK_DEG)
        source = "fallback vertical"
    else:
        angle = normalize_angle(VERTICAL_FALLBACK_DEG)
        source = "fallback"

    if APPLY_CAD_TRANSFORM:
        angle = normalize_angle(angle + cad_rotation_deg)
        source = source + " + CAD rotation"

    extra = FAMILY_ANGLE_OFFSET.get(family_name, 0.0) or 0.0
    if extra:
        angle = normalize_angle(angle + extra)
        source = source + " + family offset"

    return orientation, angle, source


def instance_origin(instance, fallback):
    try:
        loc = instance.Location
        pt = loc.Point
        if pt is not None:
            return pt
    except Exception:
        pass
    return fallback


