all_symbols = list(FilteredElementCollector(doc).OfClass(FamilySymbol))
symbol_lookup = {}
symbol_lookup_ci = {}
symbol_errors = []

for s in all_symbols:
    try:
        family_name = safe_family_name(s)
        type_name = safe_symbol_name(s)
        if family_name and type_name:
            symbol_lookup[(family_name, type_name)] = s
            symbol_lookup_ci[(family_name.upper(), type_name.upper())] = (
                family_name, type_name, s
            )
    except Exception as ex:
        symbol_errors.append(str(ex))


def lookup_pair(fname, tname):
    if (fname, tname) in symbol_lookup:
        return fname, tname, symbol_lookup[(fname, tname)]
    key_ci = (str(fname).upper(), str(tname).upper())
    if key_ci in symbol_lookup_ci:
        return symbol_lookup_ci[key_ci]
    return None


def resolve_symbol(code, fname, tname):
    """Exact map, aliases, then fuzzy type name match."""
    hit = lookup_pair(fname, tname)
    if hit:
        return hit[0], hit[1], hit[2], "exact"

    for alt_fam, alt_typ in TYPE_ALIASES.get(code, []):
        hit = lookup_pair(alt_fam, alt_typ)
        if hit:
            return hit[0], hit[1], hit[2], "alias"

    want = name_key(tname) or name_key(code)
    best = None
    for family_name, type_name in symbol_lookup.keys():
        score = score_symbol_candidate(
            code, fname, tname, family_name, type_name
        )
        if best is None or score > best[0]:
            best = (score, family_name, type_name)
    if best and best[0] >= 70:
        fam, typ = best[1], best[2]
        return fam, typ, symbol_lookup[(fam, typ)], "fuzzy:{}".format(best[0])

    return None


resolved_for_json = {}
missing = []
seen_missing = set()
for g in gondolas:
    code = normalize_code(g.get("code", ""))
    if code not in TYPE_MAP:
        continue
    fname, tname = TYPE_MAP[code]
    resolved = resolve_symbol(code, fname, tname)
    if resolved is None:
        if code not in seen_missing:
            seen_missing.add(code)
            missing.append("  {} → {} / {}".format(code, fname, tname))
    else:
        resolved_for_json[code] = resolved


# ===========================================================================
# FIND EXISTING-CONDITIONS GROUND VIEW + LEVEL
# ===========================================================================
#
# Previous runs hosted on 2.0 PROPOSED because an overlay view name
# contained "existing". The user is looking at
# "1.0 EXISTING CONDITIONS - GROUND" and saw an empty CAD underlay.

all_levels = list(FilteredElementCollector(doc).OfClass(Level))
level_map = {}
for lv in all_levels:
    try:
        if lv.Name:
            level_map[str(lv.Name)] = lv
    except Exception:
        pass

all_views = list(FilteredElementCollector(doc).OfClass(ViewPlan))
target_view = None
target_level = None
view_source = ""


def _view_ok(view):
    if view is None:
        return False
    try:
        if view.IsTemplate:
            return False
    except Exception:
        pass
    try:
        return view.GenLevel is not None
    except Exception:
        return False


def _name_score(name):
    low = str(name or "").lower()
    # User typo "Exisiting" still counts.
    low = low.replace("exisiting", "existing")
    score = 0
    if "overlay" in low:
        score -= 80
    if "proposed" in low:
        score -= 50
    if "mezzanine" in low or "mezz" in low:
        score -= 30
    if "existing" in low:
        score += 40
    if "condition" in low:
        score += 25
    if "ground" in low:
        score += 25
    if "1.0" in low or "1.0" in low.replace(" ", ""):
        score += 20
    return score


# 1) The floor plan the user currently has open.
if USE_ACTIVE_PLAN_VIEW and uidoc is not None:
    try:
        active = uidoc.ActiveView
        if isinstance(active, ViewPlan) and _view_ok(active):
            if _name_score(active.Name) >= 40:
                target_view = active
                target_level = active.GenLevel
                view_source = "active existing/ground view"
            else:
                view_source = "active view skipped ({})".format(active.Name)
    except Exception:
        target_view = None
        target_level = None

# 2) Named Existing Conditions Ground plan (screenshot view).
if target_view is None:
    wanted = TARGET_VIEW_NAME.strip().lower()
    for v in all_views:
        try:
            if not _view_ok(v):
                continue
            if str(v.Name).strip().lower() == wanted:
                target_view = v
                target_level = v.GenLevel
                view_source = "TARGET_VIEW_NAME exact"
                break
        except Exception:
            pass

if target_view is None:
    ranked = []
    for v in all_views:
        try:
            if not _view_ok(v):
                continue
            ranked.append((_name_score(v.Name), v))
        except Exception:
            pass
    ranked.sort(key=lambda row: row[0], reverse=True)
    if ranked and ranked[0][0] >= 40:
        target_view = ranked[0][1]
        target_level = target_view.GenLevel
        view_source = "best existing/ground plan view"

# 3) Level by name, then a view on that level.
if target_level is None:
    target_level = level_map.get(LEVEL_NAME)
    if target_level is None:
        for name, lv in level_map.items():
            if name.strip().lower() == LEVEL_NAME.strip().lower():
                target_level = lv
                break
    if target_level is None:
        ranked_lv = []
        for name, lv in level_map.items():
            ranked_lv.append((_name_score(name), lv))
        ranked_lv.sort(key=lambda row: row[0], reverse=True)
        if ranked_lv and ranked_lv[0][0] >= 40:
            target_level = ranked_lv[0][1]

if target_level is None:
    raise Exception(
        "Could not find the Existing Conditions Ground level.\n\n"
        "Available levels:\n{}".format(
            "\n".join("  " + n for n in sorted(level_map.keys()))
        )
    )

if target_view is None:
    for v in all_views:
        try:
            if _view_ok(v) and v.GenLevel.Id == target_level.Id:
                if _name_score(v.Name) < 0:
                    continue
                target_view = v
                view_source = "first view on target level"
                break
        except Exception:
            pass

level_override_info = "View '{}' via {} | level '{}'".format(
    target_view.Name if target_view else "(none)",
    view_source or "level fallback",
    target_level.Name,
)

if REFUSE_PROPOSED_HOST:
    host_bits = " ".join(
        [
            str(target_level.Name if target_level else ""),
            str(target_view.Name if target_view else ""),
        ]
    ).lower().replace("exisiting", "existing")
    if "proposed" in host_bits and "existing" not in host_bits:
        raise Exception(
            "Refusing to host on '{}'.\n"
            "The last run put gondolas on 2.0 PROPOSED, so they are "
            "invisible in 1.0 EXISTING CONDITIONS - GROUND even though "
            "that view is open (both levels are at 0.0).\n"
            "Open 1.0 EXISTING CONDITIONS - GROUND, replace this Python "
            "node with the latest script, and run Dynamo again.".format(
                target_level.Name if target_level else "?"
            )
        )


