# ===========================================================================
# PLACE GONDOLAS
# ===========================================================================

placed = []
placed_ids = []
skipped = []
wall_placed = []
orientation_report = []
revealed_categories = set()
cad_rotation_deg = math.degrees(cad_rotation_rad)

for g in gondolas:
    try:
        code = normalize_code(g.get("code", ""))
        if code not in TYPE_MAP:
            skipped.append("UNKNOWN CODE: {}".format(code))
            continue

        fname, tname = TYPE_MAP[code]
        resolved = resolve_symbol(code, fname, tname)
        if resolved is None:
            close = []
            for family_name, type_name in symbol_lookup.keys():
                sc = score_symbol_candidate(
                    code, fname, tname, family_name, type_name
                )
                if sc >= 30:
                    close.append((sc, family_name, type_name))
            close.sort(reverse=True)
            hint = ""
            if close:
                hint = " | closest: " + "; ".join(
                    "{} / {} ({})".format(a, b, s) for s, a, b in close[:3]
                )
            skipped.append(
                "MISSING TYPE: {} → {} / {}{}".format(code, fname, tname, hint)
            )
            continue

        fname, tname, symbol, match_how = resolved

        x_mm = float(g.get("x", 0) or 0)
        y_mm = float(g.get("y", 0) or 0)
        x_local_ft = x_mm * MM_TO_FT
        y_local_ft = y_mm * MM_TO_FT

        if APPLY_CAD_TRANSFORM and cad_transform is not None:
            try:
                mapped = cad_transform.OfPoint(XYZ(x_local_ft, y_local_ft, 0.0))
                x_ft = mapped.X
                y_ft = mapped.Y
            except Exception:
                x_ft = cad_offset_x + x_local_ft * cad_basis_xx + y_local_ft * cad_basis_yx
                y_ft = cad_offset_y + x_local_ft * cad_basis_xy + y_local_ft * cad_basis_yy
        elif APPLY_CAD_TRANSFORM:
            x_ft = cad_offset_x + x_local_ft
            y_ft = cad_offset_y + y_local_ft
        else:
            x_ft = x_local_ft
            y_ft = y_local_ft

        z_ft = target_level.Elevation
        point = XYZ(x_ft, y_ft, z_ft)

        instance = doc.Create.NewFamilyInstance(
            point,
            symbol,
            target_level,
            StructuralType.NonStructural
        )
        placed_ids.append(instance.Id)
        try:
            lv_param = instance.get_Parameter(BuiltInParameter.FAMILY_LEVEL_PARAM)
            if lv_param is not None and not lv_param.IsReadOnly:
                lv_param.Set(target_level.Id)
        except Exception:
            pass

        if target_view is not None:
            try:
                cat = instance.Category
                if cat is not None and cat.Id not in revealed_categories:
                    if target_view.GetCategoryHidden(cat.Id):
                        target_view.SetCategoryHidden(cat.Id, False)
                    revealed_categories.add(cat.Id)
            except Exception:
                pass

        if existing_phase is not None:
            try:
                p_created = instance.get_Parameter(BuiltInParameter.PHASE_CREATED)
                if p_created is not None and not p_created.IsReadOnly:
                    p_created.Set(existing_phase.Id)
            except Exception:
                pass

        if target_view is not None:
            try:
                target_view.SetElementOverrides(instance.Id, color_override)
            except Exception:
                pass

        orientation, angle_deg, angle_source = get_orientation(
            g, cad_rotation_deg, fname
        )

        if angle_deg is not None and abs(angle_deg) > 0.0001:
            rot_origin = instance_origin(instance, point)
            axis = Line.CreateBound(
                rot_origin,
                XYZ(rot_origin.X, rot_origin.Y, rot_origin.Z + 1.0),
            )
            ElementTransformUtils.RotateElement(
                doc, instance.Id, axis, math.radians(angle_deg)
            )

        placed.append(
            "{:<24} @ ({:>9.0f}, {:>9.0f}) mm angle={:>8.3f}° {} [{} / {} via {}]".format(
                code,
                x_mm,
                y_mm,
                angle_deg if angle_deg is not None else 0.0,
                angle_source,
                fname,
                tname,
                match_how,
            )
        )
        orientation_report.append(
            "{} | orientation={} | angle={:.3f}° | source={} | axis_src={}".format(
                code,
                orientation,
                angle_deg if angle_deg is not None else 0.0,
                angle_source,
                g.get("axis_source", ""),
            )
        )

        if fname in ("Wall_Gondola", "Wall_Gondola_High_Bay"):
            eid_int = safe_element_id_value(instance.Id)
            wall_placed.append(
                "{:<24} @ ({:>9.0f}, {:>9.0f}) mm angle={:>8.3f}° id={}".format(
                    code,
                    x_mm,
                    y_mm,
                    angle_deg if angle_deg is not None else 0.0,
                    eid_int,
                )
            )
    except Exception as ex:
        skipped.append("ERROR {} :: {}".format(g.get("code", "?"), str(ex)))

if target_view is not None and placed_ids:
    try:
        from System.Collections.Generic import List as NetList
        net_ids = NetList[ElementId]()
        for eid in placed_ids:
            net_ids.Add(eid)
        target_view.UnhideElements(net_ids)
    except Exception:
        pass

t.Commit()

# Jump the open view to the first placed gondola so the trace is visible
# on 1.0 EXISTING CONDITIONS - GROUND instead of an empty CAD underlay.
zoom_info = "View was not changed."
if uidoc is not None and placed_ids:
    try:
        if target_view is not None:
            uidoc.RequestViewChange(target_view)
        uidoc.ShowElements(placed_ids[0])
        zoom_info = "Opened '{}' and zoomed to first placed gondola.".format(
            target_view.Name if target_view else target_level.Name
        )
    except Exception as ex:
        zoom_info = "Could not zoom: {}".format(str(ex))


